     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;          // V 모드 함수들 → C 코드
    10→  python: string;     // Python 모드 함수들 → Python 코드
    11→  mixed: string;      // 두 코드 주석으로 구분 (디버그용)
    12→  linkFlags: string[]; // gcc 링크 플래그 (@call 에서 수집) e.g. ['-lsqlite3', '-lm']
    13→  externLibs: ExternLibInfo[]; // @call 지시문 요약
    14→}
    15→
    16→/** @call 지시문 또는 @lang 블록 하나의 요약 정보 */
    17→export interface ExternLibInfo {
    18→  lang: string;
    19→  package: string;
    20→  version?: string;
    21→  alias?: string;
    22→  linkFlags: string[];  // 이 언어/패키지에 필요한 링크 플래그
    23→  buildCmd?: string;    // 사전 빌드 명령 (Rust/Go/LangBlock 전용)
    24→  artifact?: string;    // 생성될 아티팩트 파일명 (LangBlock 전용, 예: librust.so)
    25→  sourceCode?: string;  // @lang 블록의 원본 소스 코드 (workDir에 저장할 내용)
    26→  artifactName?: string; // 소스 파일명 (예: rust_core.rs, zig_bridge.zig)
    27→  dependsOn?: string[]; // @depends_on 의존 artifact 이름들
    28→  cgo?: boolean;        // @cgo 플래그 (Go cgo 직접 호출)
    29→}
    30→
    31→// C 예약어 / 런타임 충돌 방지 목록
    32→const C_RESERVED = new Set([
    33→  'auto','break','case','char','const','continue','default','do','double',
    34→  'else','enum','extern','float','for','goto','if','inline','int','long',
    35→  'register','restrict','return','short','signed','sizeof','static','struct',
    36→  'switch','typedef','union','unsigned','void','volatile','while',
    37→  // 런타임 헬퍼 이름과도 충돌 방지
    38→  'printf','malloc','free','exit','strlen','strcmp','strdup',
    39→]);
    40→
    41→export class NexusCodegen {
    42→  private cLines: string[] = [];
    43→  private pyLines: string[] = [];
    44→  private indentLevel: number = 0;
    45→  private linkFlagsSet: Set<string> = new Set();
    46→  private externLibs: ExternLibInfo[] = [];
    47→  // 선언된 변수 추적 (스코프 스택) - 중복 선언 방지
    48→  private declaredVars: Set<string>[] = [new Set()];
    49→  // 변수명 → 타입 ('string'|'i64'|'f64'|'bool' 등)
    50→  private varTypeMap: Map<string, string> = new Map();
    51→  // Python alias 맵: alias → { package, cVar }
    52→  // @call python:numpy as np → { 'np': { pkg: 'numpy', cVar: '__fl_py_mod_np' } }
    53→  private pyAliasMap: Map<string, { pkg: string; cVar: string }> = new Map();
    54→  // Python 마샬링 헬퍼 주입 여부
    55→  private pyHelpersInjected: boolean = false;
    56→  // subprocess bridge 헬퍼 주입 여부 (ruby/node/zig 공유)
    57→  private subprocessHelpersInjected: boolean = false;
    58→
    59→  /**
    60→   * V 모드 내장 함수 처리
    61→   */
    62→  private readonly V_BUILTINS = new Set([
    63→    'println', 'print', 'len', 'to_string', 'int_cast',
    64→    // 수학
    65→    'abs', 'min', 'max', 'sqrt', 'pow', 'floor', 'ceil',
    66→    // 문자열
    67→    'str_len', 'str_contains', 'str_concat', 'str_eq',
    68→    'trim', 'split', 'lines', 'str_replace', 'char_at',
    69→    'str_slice', 'starts_with', 'ends_with', 'str_concat3',
    70→    'format', 'int_to_str', 'float_to_str',
    71→    // 파일 I/O
    72→    'read_file', 'write_file', 'append_file',
    73→    // 타입 변환
    74→    'float_cast', 'bool_cast',
    75→    // 배열
    76→    'push', 'array_len', 'array_get', 'int_array_new', 'str_array_new',
    77→    // 시스템 명령
    78→    'system',
    79→  ]);
    80→
    81→  /**
    82→   * 프로그램 전체 코드 생성
    83→   */
    84→  generate(program: AST.Program): CodegenResult {
    85→    // 1-pass: Python 모드 사용 여부 선판단
    86→    const hasPythonMode = program.body.some((item: any) =>
    87→      item.type === 'PyFunction' ||
    88→      (item.type === 'ExternCall' && item.lang === 'python')
    89→    );
    90→
    91→    // 2-pass: 코드 생성
    92→    for (const item of program.body) {
    93→      const fnItem = item as any;
    94→      if (fnItem.type === 'ExternCall') {
    95→        this.genExternCall(fnItem as AST.ExternCall);
    96→      } else if (fnItem.type === 'SharedMemDirective') {
    97→        this.genSharedMem(fnItem as AST.SharedMemDirective);
    98→      } else if (fnItem.type === 'LangBlock') {
    99→        this.genLangBlock(fnItem as AST.LangBlock);
