/**
 * FreeLang Nexus - 배열 메서드 테스트 (push/pop/slice/len)
 * IntArray/StrArray 동적 배열의 메서드 호출 지원
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

function compile(source: string): string {
  const lexer = new NexusLexer(source);
  const tokens = lexer.tokenize();
  const parser = new NexusParser(tokens);
  const ast = parser.parse();
  const codegen = new NexusCodegen();
  const result = codegen.generate(ast);
  return result.c;
}

// ==================== Test 1: IntArray push ====================
test('Test 1: arr.push(v) → fl_int_array_push(&arr, v)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(42)
  return 0
}`);
  expect(c).toContain('fl_int_array_push(&arr, 42)');
});

// ==================== Test 2: IntArray pop ====================
test('Test 2: arr.pop() → fl_int_array_pop(&arr)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(10)
  let x = arr.pop()
  return x
}`);
  expect(c).toContain('fl_int_array_pop(&arr)');
});

// ==================== Test 3: IntArray slice ====================
test('Test 3: arr.slice(s, e) → fl_int_array_slice(&arr, s, e)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(1)
  arr.push(2)
  arr.push(3)
  let s = arr.slice(0, 2)
  return 0
}`);
  expect(c).toContain('fl_int_array_slice(&arr, 0, 2)');
});

// ==================== Test 4: IntArray len ====================
test('Test 4: arr.len() → arr.len', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(1)
  let n = arr.len()
  return n
}`);
  expect(c).toContain('arr.len');
});

// ==================== Test 5: StrArray push ====================
test('Test 5: str_arr.push(s) → fl_str_array_push(&arr, s)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = str_array_new()
  arr.push("hello")
  return 0
}`);
  expect(c).toContain('fl_str_array_push(&arr, "hello")');
});

// ==================== Test 6: StrArray pop ====================
test('Test 6: str_arr.pop() → fl_str_array_pop(&arr)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = str_array_new()
  arr.push("a")
  let x = arr.pop()
  return 0
}`);
  expect(c).toContain('fl_str_array_pop(&arr)');
});

// ==================== Test 7: StrArray slice ====================
test('Test 7: str_arr.slice(0,2) → fl_str_array_slice(&arr, 0, 2)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = str_array_new()
  arr.push("a")
  arr.push("b")
  arr.push("c")
  let s = arr.slice(0, 2)
  return 0
}`);
  expect(c).toContain('fl_str_array_slice(&arr, 0, 2)');
});

// ==================== Test 8: 헤더에 pop/slice 함수 포함 ====================
test('Test 8: 런타임 헤더에 fl_int_array_pop 함수 포함', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  return 0
}`);
  expect(c).toContain('fl_int_array_pop');
  expect(c).toContain('fl_int_array_slice');
});

// ==================== Test 9: 헤더에 StrArray pop/slice 포함 ====================
test('Test 9: 런타임 헤더에 fl_str_array_pop/slice 함수 포함', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  return 0
}`);
  expect(c).toContain('fl_str_array_pop');
  expect(c).toContain('fl_str_array_slice');
});

// ==================== Test 10: ExprStatement push 코드젠 ====================
test('Test 10: ExprStatement arr.push 코드젠 세미콜론 포함', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(99)
  return 0
}`);
  expect(c).toContain('fl_int_array_push(&arr, 99);');
});

// ==================== Test 11: 연속 push 코드젠 ====================
test('Test 11: 여러 push 연속 코드젠', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(1)
  arr.push(2)
  arr.push(3)
  return 0
}`);
  expect(c).toContain('fl_int_array_push(&arr, 1)');
  expect(c).toContain('fl_int_array_push(&arr, 2)');
  expect(c).toContain('fl_int_array_push(&arr, 3)');
});

// ==================== Test 12: pop 반환값 타입 추론 ====================
test('Test 12: pop 반환값 타입 추론 (long long)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(5)
  let x = arr.pop()
  return x
}`);
  // pop() 결과가 long long 타입으로 선언되어야 함
  expect(c).toContain('long long x');
  expect(c).toContain('fl_int_array_pop(&arr)');
});

// ==================== Test 13: slice 반환값 타입 추론 ====================
test('Test 13: slice 반환값 타입 추론 (IntArray)', () => {
  const c = compile(`@mode(v)
fn test() -> i64 {
  let arr = int_array_new()
  arr.push(1)
  arr.push(2)
  let s = arr.slice(0, 1)
  return 0
}`);
  expect(c).toContain('IntArray s');
  expect(c).toContain('fl_int_array_slice(&arr, 0, 1)');
});

